153	// mirrorSuspendedOn reports whether every placement of owner/repo visible on
154	// this core is suspended. ListAvailableMirrors cannot express suspension —
155	// its status enum stops at "mirrored" — so a suspended placement reads as
156	// mirrored there; this follow-up read of the mirrors themselves keeps the
157	// checklist from showing a green rung for a mirror that will never serve.
158	// Best-effort and fail-open: an error, an absent status, or a listing that
159	// doesn't surface the placement all count as not suspended, so the probe's
160	// mirrored answer never degrades.
161	func mirrorSuspendedOn(ctx context.Context, client mirrorLister, owner, repo string) bool {
162		mirrors, err := listMirrorsForRepo(ctx, client, mirrorCloneProviderGitHub, owner, repo)
163		if err != nil {
164			logging.Debug(ctx, "onboarding: mirror suspension check failed", "error", err)
165			return false
166		}
167		if len(mirrors) == 0 {
168			return false
169		}
170		for _, m := range mirrors {
171			if m.Status.Or("") != coreapi.MirrorStatusSuspended {
172				return false
173			}
174		}
175		return true
176	}
