178	// probeRepoMirrored checks whether owner/repo has a mirror on the active
179	// context's core or the default cluster's core, consulting a short-TTL
180	// per-user cache first so hot paths (`entire status`) don't pay a network
181	// round-trip on every run. Failures are cached briefly too, so an offline
182	// terminal doesn't hang on every invocation. Owner/repo arrive lowercased
183	// from the mirror rung.
184	func probeRepoMirrored(ctx context.Context, owner, repo string) (mirrorProbeResult, error) {
185		slug := owner + "/" + repo
186		cache := defaultMirrorProbeCache()
187		now := time.Now()
188		if probe, unreachable, ok := cache.get(slug, now); ok {
189			if unreachable {
190				return mirrorProbeResult{}, errors.New("control plane unreachable (cached)")
191			}
192			return probe, nil
193		}
194		ctx, cancel := context.WithTimeout(ctx, mirrorProbeTimeout)
195		defer cancel()
196		var clients []mirrorProbeClient
197		if activeCore, err := coreapi.New(); err == nil {
198			clients = append(clients, activeCore)
199		}
200		if clusterCore, err := coreapi.NewForCluster(ctx, defaultClusterHost); err == nil {
201			clients = append(clients, clusterCore)
202		}
203		probe, err := probeMirrorAcross(ctx, clients, owner, repo)
204		if err != nil {
205			cache.putUnreachable(slug, now)
206			return mirrorProbeResult{}, err
207		}
208		cache.put(slug, probe, now)
209		return probe, nil
210	}
