212	// discoverAgentImports reports, per registered importer, how much local
213	// transcript history exists for this repo and how much of it has never been
214	// imported. Discovery is file globbing; the expensive dry-run (checkpoint
215	// store open + transcript parsing) is memoized behind a fingerprint of the
216	// discovered files and the metadata-branch tip, so an unchanged repo pays
217	// only the glob on hot paths like `entire status`. Local-only, best-effort
218	// per agent.
219	func discoverAgentImports(ctx context.Context) ([]agentImportStatus, error) {
220		repoRoot, err := paths.WorktreeRoot(ctx)
221		if err != nil {
222			return nil, fmt.Errorf("resolve worktree root: %w", err)
223		}
224		now := time.Now()
225		type discovery struct {
226			imp   agentimport.Importer
227			files []agentimport.SessionFile
228		}
229		var discovered []discovery
230		var inputs []importScanInput
231		cacheable := true
232		discoverFailures := 0
233		// Scope to agents with hooks installed — the same set the import offer
234		// acts on. Iterating every registered importer would report Missing for
235		// history the offer will never import, an unresolvable checklist row.
236		for _, ag := range installedImportAgents(ctx) {
237			imp := importerForAgent(ag)
238			if imp == nil {
239				continue
240			}
241			files, discoverErr := imp.Discover(repoRoot, "", now, nil)
242			if discoverErr != nil {
243				// Best-effort per agent, but an error is not "nothing found":
244				// don't memoize a result computed without this agent's files.
245				logging.Warn(ctx, "onboarding: transcript discovery failed", "agent", imp.Name(), "error", discoverErr)
246				discoverFailures++
247				cacheable = false
248				continue
249			}
250			if len(files) == 0 {
251				continue
252			}
253			discovered = append(discovered, discovery{imp: imp, files: files})
254			for _, f := range files {
255				info, statErr := os.Stat(f.Path)
256				if statErr != nil {
257					// A file vanished between glob and stat — don't trust a
258					// fingerprint built from a moving target.
259					cacheable = false
260					continue
261				}
262				inputs = append(inputs, importScanInput{Path: f.Path, ModTime: info.ModTime(), Size: info.Size()})
263			}
264		}
265		if len(discovered) == 0 {
266			if discoverFailures > 0 {
267				// Every answer we have is an error — "no prior history found"
268				// would be an affirmatively false settled state.
269				return nil, fmt.Errorf("transcript discovery failed for %d agent(s)", discoverFailures)
270			}
271			return nil, nil
272		}
273	
274		repo, err := openRepository(ctx)
275		if err != nil {
276			return nil, err
277		}
278		defer repo.Close()
279	
280		// The offer's import runner refuses to write under a restrictive
281		// checkpoint policy; the rung must agree, or it reports Missing forever
282		// while every consented offer silently skips.
283		if policyErr := ensureCheckpointPolicyAllowsCheckpointData(ctx, repo); policyErr != nil {
284			return nil, fmt.Errorf("%w: %w", errImportsPolicyRestricted, policyErr)
285		}
286	
287		fingerprint := importScanFingerprint(inputs, metadataBranchTip(repo))
288		cache := defaultImportScanCache()
289		if cacheable {
290			if statuses, ok := cache.get(repoRoot, fingerprint); ok {
291				return statuses, nil
292			}
293		}
294	
295		var statuses []agentImportStatus
296		runFailures := 0
297		for _, d := range discovered {
298			res, runErr := agentimport.Run(ctx, repo, d.imp, agentimport.Options{
299				RepoRoot: repoRoot, Now: now, DryRun: true,
300			})
301			if runErr != nil {
302				// Best-effort per agent, but a partial result must not be
303				// memoized — it would stay wrong until the fingerprint moves.
304				logging.Warn(ctx, "onboarding: import dry-run failed", "agent", d.imp.Name(), "error", runErr)
305				runFailures++
306				cacheable = false
307				continue
308			}
309			statuses = append(statuses, agentImportStatus{
310				Agent:           d.imp.Name(),
311				Sessions:        res.SessionsScanned,
312				UnimportedTurns: res.TurnsImported,
313				ImportedTurns:   res.TurnsSkipped,
314			})
315		}
316		if runFailures == len(discovered) {
317			// Every scan failed (typically one repo-level cause): report the
318			// failure so the rung renders Unknown instead of a false
319			// "no prior history found" / "N sessions imported".
320			return nil, fmt.Errorf("import scan failed for all %d agent(s) with history", runFailures)
321		}
322		if cacheable {
323			cache.put(repoRoot, fingerprint, statuses)
324		}
325		return statuses, nil
326	}
