338	func hooksRung(deps onboardingRungDeps) onboarding.Rung {
339		return onboarding.Rung{
340			Key:   onboarding.KeyHooks,
341			Title: "Agent hooks",
342			Check: func(ctx context.Context) onboarding.Check {
343				agents := deps.installedAgents(ctx)
344				if len(agents) == 0 {
345					return onboarding.Check{State: onboarding.StateMissing, Hint: "entire enable"}
346				}
347				return onboarding.Check{State: onboarding.StateDone, Detail: strings.Join(agents, ", ")}
348			},
349		}
350	}
