70	// ladder's import scope. (#1595 scoped to the just-selected agents; the
71	// ladder runs on resume paths too, where "installed" is the equivalent set.)
72	func installedImportAgents(ctx context.Context) []agent.Agent {
73		names := GetAgentsWithHooksInstalled(ctx)
74		out := make([]agent.Agent, 0, len(names))
75		for _, name := range names {
76			if ag, err := agent.Get(name); err == nil {
77				out = append(out, ag)
78			}
79		}
80		return out
