83	// runOnboardingMirrorCreate is the mirror rung's offer: register a mirror for
84	// the origin repo on the default cluster and return once placement is
85	// confirmed. The initial clone continues server-side (`--no-wait` semantics),
86	// so enable never blocks on a large repo's clone.
87	func runOnboardingMirrorCreate(ctx context.Context, errW io.Writer, deps onboardingRungDeps) error {
88		forge, owner, repo, err := deps.resolveOrigin(ctx)
89		if err != nil {
90			return fmt.Errorf("resolve origin: %w", err)
91		}
92		if forge != "gh" {
93			return errors.New("origin is not a GitHub repository")
94		}
95		owner, repo = githubSlug(owner, repo)
96		client, err := coreapi.NewForCluster(ctx, defaultClusterHost)
97		if err != nil {
98			return fmt.Errorf("connect to %s: %w", defaultClusterHost, err)
99		}
100		spin := startSpinner(errW, fmt.Sprintf("Mirroring %s/%s to %s", owner, repo, defaultClusterHost))
101		outcome, err := createAndAwaitMirror(ctx, client, owner, repo, defaultClusterHost,
102			true /* noWait: clone continues in the background */, 0, nil, nil)
103		spin(err == nil)
104		if err != nil {
105			return err
106		}
107		return finalizeMirrorOffer(errW, outcome)
108	}
