110	// finalizeMirrorOffer turns a nil-error createAndAwaitMirror outcome into the
111	// offer's result. A suspended placement returns nil error from the create
112	// path but will never serve — report it like `entire repo mirror create`
113	// does and return an error so the rung keeps its retry hint. (The probe-cache
114	// write-through lives in createAndAwaitMirror, which already skips suspended
115	// placements.)
116	func finalizeMirrorOffer(w io.Writer, outcome mirrorCreateOutcome) error {
117		created := outcome.created
118		if created == nil {
119			return errors.New("mirror placement not registered")
120		}
121		if created.Suspended {
122			fmt.Fprintln(w, "  WARNING: this mirror has been suspended by an admin and won't be usable.")
123			return errMirrorSuspended
124		}
125		fmt.Fprintln(w, "  Mirror registered — the initial clone continues in the background.")
126		return nil
127	}
