// runOnboardingMirrorCreate is the mirror rung's offer: register a mirror for
// the origin repo and return once placement is confirmed. The target cluster
// resolves exactly like `entire repo mirror create` with no [cluster-host] —
// catalog picker pre-selected to the caller's jurisdiction, prompting only
// when there is a real choice (resolveOfferClusterHost). The initial clone
// continues server-side (`--no-wait` semantics), so enable never blocks on a
// large repo's clone.
func runOnboardingMirrorCreate(ctx context.Context, errW io.Writer, deps onboardingRungDeps) error {
	forge, owner, repo, err := deps.resolveOrigin(ctx)
	if err != nil {
		return fmt.Errorf("resolve origin: %w", err)
	}
	if forge != "gh" {
		return errors.New("origin is not a GitHub repository")
	}
	owner, repo = githubSlug(owner, repo)
	clusterHost, err := resolveOfferClusterHost(ctx, errW)
	if err != nil {
		return err
	}
	client, err := coreapi.NewForCluster(ctx, clusterHost)
	if err != nil {
		return fmt.Errorf("connect to %s: %w", clusterHost, err)
	}
	spin := startSpinner(errW, fmt.Sprintf("Mirroring %s/%s to %s", owner, repo, clusterHost))
	outcome, err := createAndAwaitMirror(ctx, client, owner, repo, clusterHost,
		true /* noWait: clone continues in the background */, 0, nil, nil)
	spin(err == nil)
	if err != nil {
		return err
	}
	return finalizeMirrorOffer(errW, outcome)
}

