// resolveOfferClusterHost is resolveOneShotClusterHost for the enable flow's
// mirror offer, which has no cobra command (and no [cluster-host] escape
// hatch, so a failed catalog fetch surfaces as the offer's error and the
// checklist keeps its retry hint). Same shape: non-interactive keeps the
// fixed default; a terminal gets the catalog, jurisdiction-preselected,
// prompting only when there is a real choice. The offer runs after the login
// rung, so the active context the catalog fetch needs is guaranteed.
func resolveOfferClusterHost(ctx context.Context, errW io.Writer) (string, error) {
	if !interactive.CanPromptInteractively() {
		return defaultClusterHost, nil
	}
	client, err := coreapi.New()
	if err != nil {
		return "", fmt.Errorf("connect to control plane: %w", err)
	}
	stop := startSpinner(errW, "Fetching clusters")
	regions, err := availableRegions(ctx, client)
	if err != nil {
		stop(false)
		return "", err
	}
	var jurisdiction string
	// The jurisdiction only pre-selects the picker's default; a /me hiccup
	// shouldn't sink the offer, so fall back to no pre-selection.
	if me, merr := client.GetMe(ctx); merr == nil {
		jurisdiction, _ = me.Jurisdiction.Get()
	}
	stop(true)
	return chooseClusterHost(ctx, errW, regions, jurisdiction)
}

